INSERT INTO sys_perm_resource(resource_code,label)VALUES('learning_config','培训考试设置'),('learning_manage','培训计划与学时管理'),('learning_self','本人学习考试'),('learning_grade','阅卷与成绩复核'),('learning_publish','考试成绩发布'),('learning_apply','内部资格与学习结果采用')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,v.code,true,true FROM sys_role r CROSS JOIN(VALUES('learning_config'),('learning_manage'),('learning_grade'),('learning_publish'),('learning_apply'),('learning_self'))v(code)WHERE r.code IN('ty_group_hr_director','ty_company_hr_director','ty_demo_hr_manager','ty_demo_trainer')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,'learning_self',true,true FROM sys_role r WHERE r.code IN('store_staff','store_mgr','ty_demo_hr_staff','ty_demo_payroll','ty_demo_recruiter','ty_demo_trainer','ty_group_hr_director','ty_company_hr_director','ty_outsourced_person','ty_outsource_hr')ON CONFLICT DO NOTHING;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write)SELECT r.id,'learning_manage',true,false FROM sys_role r WHERE r.code='store_mgr'ON CONFLICT DO NOTHING;
-- 223: native learning, examinations and internal qualification. Not applied.
-- Depends on 220 identity/independence helpers. Existing migrations immutable.
CREATE TABLE ty_lr_course(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,name text NOT NULL,version integer NOT NULL CHECK(version>0),category text NOT NULL,chapters jsonb NOT NULL CHECK(jsonb_typeof(chapters)='array'),minimum_minutes numeric(16,4) NOT NULL DEFAULT 0 CHECK(minimum_minutes>=0),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','retired')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,code,version));
CREATE TABLE ty_lr_plan(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),code text NOT NULL,name text NOT NULL,course_id bigint REFERENCES ty_lr_course(id),starts_on date NOT NULL,ends_on date NOT NULL,capacity integer CHECK(capacity>0),required_minutes numeric(16,4) NOT NULL DEFAULT 0 CHECK(required_minutes>=0),required_practical boolean NOT NULL DEFAULT false,required_exam boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','closed','cancelled')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),CHECK(ends_on>starts_on),UNIQUE(group_id,code));
CREATE TABLE ty_lr_requirement(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),requirement_key text NOT NULL,allowed_attempts integer NOT NULL DEFAULT 1 CHECK(allowed_attempts BETWEEN 1 AND 30),held integer NOT NULL DEFAULT 0 CHECK(held>=0),used integer NOT NULL DEFAULT 0 CHECK(used>=0),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),CHECK(held+used<=allowed_attempts),UNIQUE(group_id,employment_id,requirement_key));
CREATE TABLE ty_lr_assignment(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),plan_id bigint NOT NULL REFERENCES ty_lr_plan(id),mandatory boolean NOT NULL DEFAULT true,state text NOT NULL DEFAULT 'assigned' CHECK(state IN('requested','waitlist','assigned','completed','cancelled','rejected')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),decided_by bigint REFERENCES sys_account(id),reason text,completed_at timestamptz,UNIQUE(plan_id,requirement_id));
CREATE TABLE ty_lr_progress(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,assignment_id bigint NOT NULL REFERENCES ty_lr_assignment(id),chapter_key text NOT NULL,segments jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(segments)='array'),acknowledged boolean NOT NULL DEFAULT false,revision integer NOT NULL DEFAULT 1,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),recorded_by bigint NOT NULL REFERENCES sys_account(id),UNIQUE(assignment_id,chapter_key));
CREATE TABLE ty_lr_session(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),plan_id bigint NOT NULL REFERENCES ty_lr_plan(id),name text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,capacity integer CHECK(capacity>0),trainer_id bigint NOT NULL REFERENCES sys_account(id),location text NOT NULL,required boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),CHECK(ends_at>starts_at));
CREATE TABLE ty_lr_attendance(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),assignment_id bigint NOT NULL REFERENCES ty_lr_assignment(id),session_id bigint NOT NULL REFERENCES ty_lr_session(id),version integer NOT NULL DEFAULT 1,check_in timestamptz,check_out timestamptz,credited_minutes numeric(16,4),attendance_state text NOT NULL CHECK(attendance_state IN('present','late','early','absent','excused','pending')),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','verified','rejected')),source_ref text NOT NULL,revision integer NOT NULL DEFAULT 1,submitted_by bigint NOT NULL REFERENCES sys_account(id),verified_by bigint REFERENCES sys_account(id),verification_ref text,CHECK(check_out IS NULL OR check_in IS NOT NULL AND check_out>=check_in),CHECK(credited_minutes IS NULL OR credited_minutes>=0),UNIQUE(assignment_id,session_id,version));
CREATE TABLE ty_lr_practical(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),assignment_id bigint NOT NULL REFERENCES ty_lr_assignment(id),version integer NOT NULL,score numeric(18,6) CHECK(score BETWEEN 0 AND 100),passed boolean NOT NULL,criteria jsonb NOT NULL,evidence_ref text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','verified','rejected')),revision integer NOT NULL DEFAULT 1,submitted_by bigint NOT NULL REFERENCES sys_account(id),verified_by bigint REFERENCES sys_account(id),reason text,UNIQUE(assignment_id,version));
CREATE TABLE ty_lr_discipline(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),assignment_id bigint NOT NULL REFERENCES ty_lr_assignment(id),kind text NOT NULL CHECK(kind IN('late','absent','misconduct','commendation','other')),description text NOT NULL,source_ref text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','verified','rejected')),revision integer NOT NULL DEFAULT 1,submitted_by bigint NOT NULL REFERENCES sys_account(id),verified_by bigint REFERENCES sys_account(id),reason text);
CREATE TABLE ty_lr_question(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,version integer NOT NULL,kind text NOT NULL CHECK(kind IN('single','multi','judge','fill','short','attachment')),category text NOT NULL,difficulty text NOT NULL,prompt text NOT NULL,options jsonb NOT NULL DEFAULT '[]',points numeric(18,6) NOT NULL CHECK(points>0),grading jsonb NOT NULL DEFAULT '{}',rubric text,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','retired')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),UNIQUE(group_id,code,version));
CREATE TABLE ty_lr_question_key(question_id bigint PRIMARY KEY REFERENCES ty_lr_question(id),answer jsonb NOT NULL);
CREATE TABLE ty_lr_paper(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,name text NOT NULL,version integer NOT NULL,selection jsonb NOT NULL,pass_percentage numeric(18,6) NOT NULL CHECK(pass_percentage BETWEEN 0 AND 100),shuffle boolean NOT NULL DEFAULT false,pool_snapshot jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','retired')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),UNIQUE(group_id,code,version));
CREATE TABLE ty_lr_exam(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),plan_id bigint REFERENCES ty_lr_plan(id),paper_id bigint NOT NULL REFERENCES ty_lr_paper(id),name text NOT NULL,opens_at timestamptz NOT NULL,closes_at timestamptz NOT NULL,duration_minutes integer NOT NULL CHECK(duration_minutes BETWEEN 1 AND 1440),maximum_attempts integer NOT NULL CHECK(maximum_attempts BETWEEN 1 AND 30),retake_interval_minutes integer NOT NULL DEFAULT 0 CHECK(retake_interval_minutes>=0),grader_id bigint NOT NULL REFERENCES sys_account(id),reviewer_id bigint NOT NULL REFERENCES sys_account(id),answer_policy text NOT NULL DEFAULT 'never' CHECK(answer_policy IN('never','after_window')),result_policy text NOT NULL DEFAULT 'highest' CHECK(result_policy IN('first','highest','latest','latest_pass')),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','cancelled','closed')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),CHECK(closes_at>opens_at));
CREATE TABLE ty_lr_exam_assignment(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,exam_id bigint NOT NULL REFERENCES ty_lr_exam(id),requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),state text NOT NULL DEFAULT 'active' CHECK(state IN('active','cancelled')),created_by bigint NOT NULL REFERENCES sys_account(id),UNIQUE(exam_id,requirement_id));
CREATE TABLE ty_lr_attempt(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),exam_id bigint NOT NULL REFERENCES ty_lr_exam(id),ordinal integer NOT NULL,status text NOT NULL DEFAULT 'in_progress' CHECK(status IN('in_progress','submitted','void')),question_snapshot jsonb NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),deadline_at timestamptz NOT NULL,deadline_revision integer NOT NULL DEFAULT 1,answer_revision integer NOT NULL DEFAULT 0,submitted_at timestamptz,submitted_answer_revision integer,void_ref text,exception_by bigint REFERENCES sys_account(id),revision integer NOT NULL DEFAULT 1,started_by bigint NOT NULL REFERENCES sys_account(id),CHECK(deadline_at>started_at),UNIQUE(requirement_id,ordinal));
CREATE UNIQUE INDEX ty_lr_one_open_attempt ON ty_lr_attempt(requirement_id) WHERE status='in_progress';
CREATE TABLE ty_lr_answer(attempt_id bigint NOT NULL REFERENCES ty_lr_attempt(id),question_id bigint NOT NULL REFERENCES ty_lr_question(id),value jsonb NOT NULL,answer_revision integer NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),recorded_by bigint NOT NULL REFERENCES sys_account(id),PRIMARY KEY(attempt_id,question_id));
CREATE TABLE ty_lr_quota_event(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),attempt_id bigint NOT NULL REFERENCES ty_lr_attempt(id),kind text NOT NULL CHECK(kind IN('hold','settle','release','restore')),held_delta integer NOT NULL,used_delta integer NOT NULL,source_key text NOT NULL UNIQUE,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ty_lr_grade(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),attempt_id bigint REFERENCES ty_lr_attempt(id),version integer NOT NULL,previous_id bigint REFERENCES ty_lr_grade(id),marks jsonb NOT NULL DEFAULT '{}',score numeric(18,6),maximum_score numeric(18,6) NOT NULL CHECK(maximum_score>0),percentage numeric(18,6),pass_percentage numeric(18,6) NOT NULL CHECK(pass_percentage BETWEEN 0 AND 100),passed boolean,source_hash text NOT NULL,source_kind text NOT NULL CHECK(source_kind IN('exam','historical')),source_ref text NOT NULL,status text NOT NULL DEFAULT 'proposed' CHECK(status IN('proposed','approved','rejected')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approval_instance_id bigint REFERENCES ty_workflow_instance(id),reason text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(score IS NULL OR score BETWEEN 0 AND maximum_score),CHECK(percentage IS NULL OR percentage BETWEEN 0 AND 100));
CREATE UNIQUE INDEX ty_lr_grade_version ON ty_lr_grade(requirement_id,coalesce(attempt_id,0),version);
CREATE TABLE ty_lr_publication(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,grade_id bigint NOT NULL UNIQUE REFERENCES ty_lr_grade(id),published_by bigint NOT NULL REFERENCES sys_account(id),published_at timestamptz NOT NULL DEFAULT now(),acknowledged_at timestamptz,acknowledged_by bigint REFERENCES sys_account(id));
CREATE TABLE ty_lr_appeal(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),publication_id bigint NOT NULL REFERENCES ty_lr_publication(id),reason text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','upheld','corrected','rejected')),corrected_grade_id bigint REFERENCES ty_lr_grade(id),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),decided_by bigint REFERENCES sys_account(id),decision_ref text);
CREATE TABLE ty_lr_certificate(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN('internal_completion','internal_skill')),conditions jsonb NOT NULL,valid_months integer CHECK(valid_months BETWEEN 1 AND 120),recognition_mode text NOT NULL CHECK(recognition_mode IN('once','continuous')),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','retired')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),UNIQUE(group_id,code));
CREATE TABLE ty_lr_recognition(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),certificate_id bigint NOT NULL REFERENCES ty_lr_certificate(id),grade_id bigint REFERENCES ty_lr_grade(id),serial text NOT NULL UNIQUE,valid_from date NOT NULL,valid_to date,status text NOT NULL DEFAULT 'proposed' CHECK(status IN('proposed','approved','revoked','rejected')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),source_hash text NOT NULL,evidence_ref text NOT NULL,revocation_ref text,CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE TABLE ty_lr_rule(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),code text NOT NULL,name text NOT NULL,target text NOT NULL CHECK(target IN('payroll','performance')),purpose_code text NOT NULL,config jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','retired')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),published_by bigint REFERENCES sys_account(id),UNIQUE(group_id,code));
CREATE TABLE ty_lr_application(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),rule_id bigint NOT NULL REFERENCES ty_lr_rule(id),grade_id bigint REFERENCES ty_lr_grade(id),recognition_id bigint REFERENCES ty_lr_recognition(id),target_assignment_id bigint,source_snapshot jsonb NOT NULL,source_hash text NOT NULL,status text NOT NULL DEFAULT 'proposed' CHECK(status IN('proposed','approved','applied','cancelled','rejected','blocked')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),applied_by bigint REFERENCES sys_account(id),approval_instance_id bigint REFERENCES ty_workflow_instance(id),reason text NOT NULL,result jsonb);
CREATE TABLE ty_lr_award_parent(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),requirement_id bigint NOT NULL REFERENCES ty_lr_requirement(id),purpose_code text NOT NULL,item_code text NOT NULL,currency text NOT NULL CHECK(currency IN('CNY','HKD')),mode text NOT NULL CHECK(mode IN('once','monthly')),current_application_id bigint REFERENCES ty_lr_application(id),head_revision integer NOT NULL DEFAULT 0,UNIQUE(group_id,employment_id,requirement_id,purpose_code));
CREATE TABLE ty_lr_notice(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),recipient_id bigint NOT NULL REFERENCES sys_account(id),event_key text NOT NULL,kind text NOT NULL,title text NOT NULL,entity_type text NOT NULL,entity_id bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,UNIQUE(recipient_id,event_key));
CREATE TABLE ty_lr_import(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),kind text NOT NULL CHECK(kind IN('questions','historical_grades','attendance')),namespace text NOT NULL,sha256 text NOT NULL,rows jsonb NOT NULL,issues jsonb NOT NULL,status text NOT NULL CHECK(status IN('validated','invalid','applied')),revision integer NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,kind,namespace,sha256));

CREATE FUNCTION fn_ty_lr_hash(v jsonb)RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT encode(sha256(convert_to(v::text,'UTF8')),'hex')$$;
CREATE FUNCTION fn_ty_lr_scope_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE e public.ty_employment%ROWTYPE;c public.ty_company%ROWTYPE;r public.ty_lr_requirement%ROWTYPE;j jsonb=to_jsonb(NEW);BEGIN
 IF j?'company_id'AND j->>'company_id'IS NOT NULL THEN SELECT * INTO c FROM public.ty_company WHERE id=(j->>'company_id')::bigint;IF c.id IS NULL OR c.group_id<>(j->>'group_id')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 学习公司不属于集团';END IF;END IF;
 IF j?'employment_id' THEN SELECT * INTO e FROM public.ty_employment WHERE id=(j->>'employment_id')::bigint;IF e.id IS NULL OR (e.group_id,e.company_id,e.person_id)IS DISTINCT FROM((j->>'group_id')::bigint,(j->>'company_id')::bigint,(j->>'person_id')::bigint)OR e.status='cancelled' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 学习事实必须同集团永久人真实雇佣';END IF;END IF;
 IF j?'requirement_id'THEN SELECT * INTO r FROM public.ty_lr_requirement WHERE id=(j->>'requirement_id')::bigint;IF(r.group_id,r.company_id,r.person_id,r.employment_id)IS DISTINCT FROM((j->>'group_id')::bigint,(j->>'company_id')::bigint,(j->>'person_id')::bigint,(j->>'employment_id')::bigint)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 学习要求根不可换人换雇佣';END IF;END IF;RETURN NEW;END;$$;
CREATE FUNCTION fn_ty_lr_frozen_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE o jsonb=to_jsonb(OLD);n jsonb=to_jsonb(NEW);s text=coalesce(o->>'status',o->>'state');BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 学习考试历史不可删除';END IF;
 IF (n-ARRAY['revision','status','state','published_by','approved_by','verified_by','reason','verification_ref','decided_by','revocation_ref','completed_at','current_application_id','head_revision','held','used','allowed_attempts','decided_at','decision_ref','corrected_grade_id','acknowledged_at','acknowledged_by','read_at','applied_by','result','approval_instance_id'])IS DISTINCT FROM(o-ARRAY['revision','status','state','published_by','approved_by','verified_by','reason','verification_ref','decided_by','revocation_ref','completed_at','current_application_id','head_revision','held','used','allowed_attempts','decided_at','decision_ref','corrected_grade_id','acknowledged_at','acknowledged_by','read_at','applied_by','result','approval_instance_id'])AND s NOT IN('draft','requested','waitlist','assigned') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已提交事实不可覆盖，须保留更正版';END IF;
 IF TG_TABLE_NAME IN('ty_lr_grade','ty_lr_attendance','ty_lr_practical','ty_lr_discipline')AND s IN('approved','verified','rejected')AND n IS DISTINCT FROM o THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已核准学习事实不能覆盖';END IF;RETURN NEW;END;$$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['course','plan','requirement','assignment','session','attendance','practical','discipline','question','paper','exam','grade','appeal','certificate','recognition','rule','application','award_parent','notice','import']LOOP EXECUTE format('CREATE TRIGGER ty_lr_%s_scope BEFORE INSERT OR UPDATE ON ty_lr_%s FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_scope_guard()',n,n);EXECUTE format('CREATE TRIGGER ty_lr_%s_frozen BEFORE UPDATE OR DELETE ON ty_lr_%s FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_frozen_guard()',n,n);END LOOP;END$$;
-- Permanently retained exact quota events, not reset by a new exam task.
CREATE FUNCTION fn_ty_lr_quota_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE r public.ty_lr_requirement%ROWTYPE;a public.ty_lr_attempt%ROWTYPE;BEGIN IF TG_OP<>'INSERT'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 考试次数流水不可改写';END IF;SELECT * INTO r FROM public.ty_lr_requirement WHERE id=NEW.requirement_id FOR UPDATE;SELECT * INTO a FROM public.ty_lr_attempt WHERE id=NEW.attempt_id;IF a.requirement_id<>r.id OR NEW.kind='hold'AND(NEW.held_delta<>1 OR NEW.used_delta<>0)OR NEW.kind='settle'AND(NEW.held_delta<>-1 OR NEW.used_delta<>1)OR NEW.kind='release'AND(NEW.held_delta<>-1 OR NEW.used_delta<>0)OR NEW.kind='restore'AND(NEW.held_delta<>0 OR NEW.used_delta<>-1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 考试次数流水不守恒';END IF;UPDATE public.ty_lr_requirement SET held=held+NEW.held_delta,used=used+NEW.used_delta,revision=revision+1 WHERE id=r.id;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_quota_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_lr_quota_event FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_quota_guard();
CREATE FUNCTION fn_ty_lr_answer_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE a public.ty_lr_attempt%ROWTYPE;BEGIN SELECT * INTO a FROM public.ty_lr_attempt WHERE id=NEW.attempt_id FOR UPDATE;IF a.status<>'in_progress'OR clock_timestamp()>=a.deadline_at OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.question_snapshot)x WHERE(x->>'id')::bigint=NEW.question_id)OR NEW.answer_revision<>a.answer_revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 答卷已封存、截止或答案修订不符';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_answer_guard BEFORE INSERT OR UPDATE ON ty_lr_answer FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_answer_guard();
CREATE FUNCTION fn_ty_lr_attempt_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE e public.ty_lr_exam%ROWTYPE;r public.ty_lr_requirement%ROWTYPE;BEGIN
 SELECT * INTO e FROM public.ty_lr_exam WHERE id=NEW.exam_id;SELECT * INTO r FROM public.ty_lr_requirement WHERE id=NEW.requirement_id FOR UPDATE;
 IF TG_OP='INSERT'THEN IF e.status<>'published'OR clock_timestamp()<e.opens_at OR clock_timestamp()>=e.closes_at OR r.held+r.used>=r.allowed_attempts OR NOT EXISTS(SELECT 1 FROM public.ty_lr_exam_assignment x WHERE x.exam_id=e.id AND x.requirement_id=r.id AND x.state='active')OR e.group_id<>r.group_id OR e.company_id IS NOT NULL AND NOT public.fn_ty_lr_company_contains(e.company_id,r.company_id) OR NEW.deadline_at>least(e.closes_at,NEW.started_at+make_interval(mins=>e.duration_minutes))OR NEW.started_at>clock_timestamp()+interval '2 seconds'OR NEW.started_at<clock_timestamp()-interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 开考资格、服务器时间或共享次数不符';END IF;
 ELSE IF OLD.status<>'in_progress'AND NOT(OLD.status='submitted'AND NEW.status='void'AND NEW.void_ref IS NOT NULL AND NEW.exception_by IS NOT NULL)AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已封卷不能重开或改答案';END IF;IF (NEW.question_snapshot,NEW.requirement_id,NEW.exam_id,NEW.started_at,NEW.started_by)IS DISTINCT FROM(OLD.question_snapshot,OLD.requirement_id,OLD.exam_id,OLD.started_at,OLD.started_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 在考快照不能换卷换人';END IF;IF (NEW.deadline_at<>OLD.deadline_at OR NEW.status='void')AND(NEW.exception_by IS NULL OR public.fn_ty_pr_same_actor(NEW.exception_by,OLD.started_by)OR public.fn_ty_pr_actor_is_person(NEW.exception_by,OLD.group_id,OLD.person_id)OR length(coalesce(NEW.void_ref,''))<4)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 考试例外须独立签署并留依据';END IF;IF NEW.deadline_at<>OLD.deadline_at AND NEW.deadline_revision<>OLD.deadline_revision+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 延期必须形成新截止版本';END IF;IF NEW.status='submitted'AND NEW.submitted_answer_revision IS DISTINCT FROM OLD.answer_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 交卷须确认最后已保存答案版本';END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_attempt_rules BEFORE INSERT OR UPDATE ON ty_lr_attempt FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_attempt_guard();
CREATE FUNCTION fn_ty_lr_grade_values(p_attempt bigint,p_marks jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE a public.ty_lr_attempt%ROWTYPE;x jsonb;v jsonb;pts numeric;got numeric;total numeric=0;maximum numeric=0;complete boolean=true;chosen text[];correct text[];BEGIN SELECT * INTO a FROM public.ty_lr_attempt WHERE id=p_attempt;IF a.status<>'submitted'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 尚未封卷';END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(a.question_snapshot)LOOP pts=(x->>'points')::numeric;maximum=maximum+pts;SELECT value INTO v FROM public.ty_lr_answer WHERE attempt_id=a.id AND question_id=(x->>'id')::bigint;got=0;
 IF x->>'kind'IN('short','attachment')THEN IF NOT p_marks?(x->>'id')THEN complete=false;ELSE got=(p_marks->(x->>'id')->>'score')::numeric;IF got<0 OR got>pts OR length(coalesce(p_marks->(x->>'id')->>'reason',''))<3 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 人工阅卷须有效分数及理由';END IF;END IF;
 ELSIF x->>'kind'='multi'THEN SELECT array_agg(z ORDER BY z)INTO chosen FROM(SELECT DISTINCT jsonb_array_elements_text(coalesce(v,'[]'))z)s;SELECT array_agg(z ORDER BY z)INTO correct FROM(SELECT DISTINCT jsonb_array_elements_text(x->'answer')z)s;IF chosen=correct THEN got=pts;ELSIF coalesce((x->'grading'->>'partial_multi')::boolean,false)AND cardinality(chosen)>0 AND chosen<@correct THEN got=pts*cardinality(chosen)/cardinality(correct);END IF;
 ELSIF x->>'kind'='fill'THEN IF coalesce((x->'grading'->>'case_sensitive')::boolean,false)THEN IF v=x->'answer'THEN got=pts;END IF;ELSE IF lower(trim(coalesce(v#>>'{}','')))=lower(trim(x->'answer'#>>'{}'))THEN got=pts;END IF;END IF;
 ELSE IF v=x->'answer'THEN got=pts;END IF;END IF;total=total+got;END LOOP;
 RETURN jsonb_build_object('score',CASE WHEN complete THEN round(total,6)::text END,'maximum_score',maximum::text,'percentage',CASE WHEN complete THEN round(total*100/nullif(maximum,0),6)::text END,'complete',complete);END;$$;
CREATE FUNCTION fn_ty_lr_business_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE j jsonb=to_jsonb(NEW);creator bigint=coalesce((j->>'created_by')::bigint,(j->>'submitted_by')::bigint);reviewer bigint=coalesce((j->>'approved_by')::bigint,(j->>'verified_by')::bigint,(j->>'published_by')::bigint);g bigint=(j->>'group_id')::bigint;p bigint=(j->>'person_id')::bigint;s text=coalesce(j->>'status',j->>'state');a public.ty_lr_attempt%ROWTYPE;v jsonb;plan public.ty_lr_plan%ROWTYPE;r public.ty_lr_requirement%ROWTYPE;cer public.ty_lr_certificate%ROWTYPE;gr public.ty_lr_grade%ROWTYPE;BEGIN
 IF reviewer IS NOT NULL AND(creator IS NOT NULL AND public.fn_ty_pr_same_actor(reviewer,creator)OR p IS NOT NULL AND public.fn_ty_pr_actor_is_person(reviewer,g,p))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 培训复核须非制单人、非受益自然人';END IF;
 IF TG_TABLE_NAME='ty_lr_assignment'THEN SELECT * INTO plan FROM public.ty_lr_plan WHERE id=NEW.plan_id;SELECT * INTO r FROM public.ty_lr_requirement WHERE id=NEW.requirement_id;IF plan.group_id<>NEW.group_id OR plan.company_id IS NOT NULL AND NOT public.fn_ty_lr_company_contains(plan.company_id,NEW.company_id) OR plan.status<>'published'OR NOT EXISTS(SELECT 1 FROM public.ty_employment e WHERE e.id=NEW.employment_id AND e.hire_date<plan.ends_on AND(e.leave_date IS NULL OR e.leave_date>=plan.starts_on))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 学习任务必须覆盖真实关系与已发布计划';END IF;END IF;
 IF TG_TABLE_NAME='ty_lr_grade'THEN IF NEW.source_kind='exam'THEN SELECT * INTO a FROM public.ty_lr_attempt WHERE id=NEW.attempt_id;IF (a.group_id,a.company_id,a.person_id,a.employment_id,a.requirement_id)IS DISTINCT FROM(NEW.group_id,NEW.company_id,NEW.person_id,NEW.employment_id,NEW.requirement_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 成绩必须同答卷真实身份';END IF;v=public.fn_ty_lr_grade_values(a.id,NEW.marks);IF NEW.score IS DISTINCT FROM(v->>'score')::numeric OR NEW.maximum_score IS DISTINCT FROM(v->>'maximum_score')::numeric OR NEW.percentage IS DISTINCT FROM(v->>'percentage')::numeric OR NEW.source_hash<>public.fn_ty_lr_hash(jsonb_build_object('attempt_id',a.id,'answer_revision',a.answer_revision,'questions',a.question_snapshot,'answers',(SELECT coalesce(jsonb_agg(jsonb_build_object('question_id',x.question_id,'value',x.value)ORDER BY x.question_id),'[]'::jsonb)FROM public.ty_lr_answer x WHERE x.attempt_id=a.id),'marks',NEW.marks))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 分数或来源非冻结答案权威复算';END IF;ELSE IF NEW.percentage IS DISTINCT FROM round(NEW.score*100/NEW.maximum_score,6)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 历史成绩比例必须真实复算';END IF;IF NEW.attempt_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 历史成绩不能伪造答卷';END IF;END IF;IF NEW.passed IS DISTINCT FROM(NEW.percentage>=NEW.pass_percentage)OR NEW.status='approved'AND(NEW.score IS NULL OR NEW.approved_by IS NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 未完成阅卷不能合格或正式核准';END IF;END IF;
 IF TG_TABLE_NAME='ty_lr_recognition'THEN SELECT * INTO cer FROM public.ty_lr_certificate WHERE id=NEW.certificate_id;SELECT * INTO gr FROM public.ty_lr_grade WHERE id=NEW.grade_id;IF cer.group_id<>NEW.group_id OR cer.status<>'published'OR coalesce((cer.conditions->>'exam_passed')::boolean,false)AND(gr.status<>'approved'OR gr.passed IS DISTINCT FROM true OR gr.requirement_id<>NEW.requirement_id OR NOT EXISTS(SELECT 1 FROM public.ty_lr_publication WHERE grade_id=gr.id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 内部资格须同人已发布核准条件';END IF;END IF;
 RETURN NEW;END;$$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['course','plan','assignment','attendance','practical','discipline','question','paper','exam','grade','certificate','recognition','rule','application']LOOP EXECUTE format('CREATE TRIGGER ty_lr_%s_rules BEFORE INSERT OR UPDATE ON ty_lr_%s FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_business_guard()',n,n);END LOOP;END$$;
-- Prevent unsupported public answer-key mutation after a reviewed question.
CREATE FUNCTION fn_ty_lr_key_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF TG_OP='DELETE'OR EXISTS(SELECT 1 FROM public.ty_lr_question WHERE id=coalesce(NEW.question_id,OLD.question_id)AND status<>'draft')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已发布答案键不可改写';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_key_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_lr_question_key FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_key_guard();

ALTER TABLE ty_lr_import RENAME COLUMN sha256 TO source_hash;ALTER TABLE ty_lr_import RENAME COLUMN rows TO parsed_rows;ALTER TABLE ty_lr_import ADD COLUMN filename text NOT NULL;
CREATE FUNCTION fn_ty_lr_no_delete()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 培训考试历史不可删除';END;$$;
CREATE TRIGGER ty_lr_attempt_no_delete BEFORE DELETE ON ty_lr_attempt FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_no_delete();
CREATE TRIGGER ty_lr_progress_no_delete BEFORE DELETE ON ty_lr_progress FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_no_delete();
CREATE TRIGGER ty_lr_answer_no_delete BEFORE DELETE ON ty_lr_answer FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_no_delete();
CREATE TRIGGER ty_lr_publication_no_delete BEFORE DELETE ON ty_lr_publication FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_no_delete();
CREATE TRIGGER ty_lr_question_key_no_delete BEFORE DELETE ON ty_lr_question_key FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_no_delete();
CREATE TRIGGER ty_lr_exam_assignment_no_delete BEFORE DELETE ON ty_lr_exam_assignment FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_no_delete();
ALTER TABLE ty_lr_application ADD COLUMN expected_award_head integer NOT NULL DEFAULT 0;
CREATE FUNCTION fn_ty_lr_award_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE a public.ty_lr_application%ROWTYPE;r public.ty_lr_rule%ROWTYPE;BEGIN
 IF TG_OP='UPDATE'THEN IF (NEW.group_id,NEW.company_id,NEW.person_id,NEW.employment_id,NEW.requirement_id,NEW.purpose_code,NEW.item_code,NEW.currency,NEW.mode)IS DISTINCT FROM(OLD.group_id,OLD.company_id,OLD.person_id,OLD.employment_id,OLD.requirement_id,OLD.purpose_code,OLD.item_code,OLD.currency,OLD.mode)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 稳定培训奖励父义务不得换人换根';END IF;
 IF NEW.current_application_id IS DISTINCT FROM OLD.current_application_id THEN SELECT*INTO a FROM public.ty_lr_application WHERE id=NEW.current_application_id;SELECT*INTO r FROM public.ty_lr_rule WHERE id=a.rule_id;IF a.status<>'approved'OR a.expected_award_head<>OLD.head_revision OR NEW.head_revision<>OLD.head_revision+1 OR (a.group_id,a.company_id,a.person_id,a.employment_id,a.requirement_id)IS DISTINCT FROM(NEW.group_id,NEW.company_id,NEW.person_id,NEW.employment_id,NEW.requirement_id)OR r.target<>'payroll'OR r.purpose_code<>NEW.purpose_code OR r.config->>'item_code'<>NEW.item_code OR r.config->>'currency'<>NEW.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 培训奖励须同一已批准采用及父根CAS';END IF;END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_award_guard BEFORE UPDATE ON ty_lr_award_parent FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_award_guard();
CREATE FUNCTION fn_ty_lr_award_target(parent_key bigint,period_key date)RETURNS numeric LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE p public.ty_lr_award_parent%ROWTYPE;a public.ty_lr_application%ROWTYPE;r public.ty_lr_rule%ROWTYPE;g public.ty_lr_grade%ROWTYPE;qual public.ty_lr_recognition%ROWTYPE;cfg jsonb;from_day date;to_day date;n integer;denom integer;BEGIN
 SELECT*INTO p FROM public.ty_lr_award_parent WHERE id=parent_key;SELECT*INTO a FROM public.ty_lr_application WHERE id=p.current_application_id;SELECT*INTO r FROM public.ty_lr_rule WHERE id=a.rule_id;cfg=r.config;
 IF p.id IS NULL OR a.status<>'applied'OR r.status<>'published'OR r.target<>'payroll'OR EXISTS(SELECT 1 FROM public.ty_lr_appeal x JOIN public.ty_lr_publication y ON y.id=x.publication_id JOIN public.ty_lr_grade z ON z.id=y.grade_id WHERE z.requirement_id=p.requirement_id AND x.status='pending')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 培训待遇未生效或成绩有未结争议';END IF;
 IF a.grade_id IS NOT NULL THEN SELECT*INTO g FROM public.ty_lr_grade WHERE id=a.grade_id;IF g.status<>'approved'OR NOT EXISTS(SELECT 1 FROM public.ty_lr_publication WHERE grade_id=g.id)OR EXISTS(SELECT 1 FROM public.ty_lr_grade WHERE status='approved'AND(previous_id=g.id OR g.attempt_id IS NOT NULL AND attempt_id=g.attempt_id AND version>g.version))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源成绩已更正或未核准发布';END IF;END IF;
 IF coalesce((cfg->>'require_qualification')::boolean,false)THEN SELECT*INTO qual FROM public.ty_lr_recognition WHERE id=a.recognition_id;IF qual.status IS DISTINCT FROM'approved'OR NOT public.fn_ty_lr_recognition_current(qual.id,qual.valid_from)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 必需内部资格待核或撤销';END IF;END IF;
 IF p.mode='once'THEN IF to_date(cfg->>'payout_period','YYYY-MM')<>period_key THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 奖励发放月不匹配';END IF;RETURN(cfg->>'amount')::numeric;END IF;
 from_day=greatest(period_key,(cfg->>'valid_from')::date);to_day=least((period_key+interval '1 month')::date,coalesce((cfg->>'valid_to')::date,(period_key+interval '1 month')::date));
 IF qual.id IS NOT NULL AND coalesce((cfg->>'require_current_qualification')::boolean,false)THEN from_day=greatest(from_day,qual.valid_from);to_day=least(to_day,coalesce(qual.valid_to,to_day));END IF;n=greatest(0,to_day-from_day);denom=(period_key+interval '1 month')::date-period_key;RETURN round((cfg->>'amount')::numeric*n/denom,2);END;$$;
CREATE FUNCTION fn_ty_lr_pay_key(batch_key bigint,adoption_key bigint)RETURNS text LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE a public.ty_pay_adoption%ROWTYPE;b public.ty_pay_batch%ROWTYPE;l public.ty_lr_application%ROWTYPE;p public.ty_lr_award_parent%ROWTYPE;o public.ty_pay_obligation%ROWTYPE;i public.ty_pay_item%ROWTYPE;BEGIN SELECT*INTO a FROM public.ty_pay_adoption WHERE id=adoption_key AND batch_id=batch_key;SELECT*INTO b FROM public.ty_pay_batch WHERE id=batch_key;SELECT*INTO l FROM public.ty_lr_application WHERE id=a.source_id::bigint;SELECT*INTO p FROM public.ty_lr_award_parent WHERE current_application_id=l.id;SELECT*INTO o FROM public.ty_pay_obligation WHERE id=a.obligation_id;SELECT*INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;
 IF a.source_domain<>'training_award'OR p.id IS NULL OR p.group_id<>b.group_id OR p.company_id<>b.company_id OR p.person_id IS DISTINCT FROM o.person_id OR p.employment_id IS DISTINCT FROM o.employment_id OR p.item_code IS DISTINCT FROM i.code OR p.currency<>b.currency THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 培训待遇必须反查同一人雇佣项目币种权威根';END IF;RETURN CASE WHEN p.mode='once'THEN'training_award:'||p.id ELSE'training_allowance:'||p.id||':'||to_char(b.period,'YYYY-MM')END;END;$$;
CREATE FUNCTION fn_ty_lr_pay_expected(batch_key bigint,adoption_key bigint)RETURNS numeric LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE a public.ty_pay_adoption%ROWTYPE;b public.ty_pay_batch%ROWTYPE;l public.ty_lr_application%ROWTYPE;p public.ty_lr_award_parent%ROWTYPE;book public.ty_pay_config%ROWTYPE;tags jsonb;BEGIN PERFORM public.fn_ty_lr_pay_key(batch_key,adoption_key);SELECT*INTO a FROM public.ty_pay_adoption WHERE id=adoption_key;SELECT*INTO b FROM public.ty_pay_batch WHERE id=batch_key;SELECT*INTO l FROM public.ty_lr_application WHERE id=a.source_id::bigint;SELECT*INTO p FROM public.ty_lr_award_parent WHERE current_application_id=l.id;IF a.source_revision<>(l.revision||':'||p.head_revision)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 培训待遇来源修订已变';END IF;SELECT*INTO book FROM public.ty_pay_config WHERE id=b.rulebook_id;tags=book.data->'source_treatments'->'training_award'->p.item_code;IF tags?'wage_tags'THEN tags=tags->'wage_tags';END IF;
 IF tags IS NULL OR NOT(tags?'hk_adw'AND tags?'cn_average'AND tags?'cn_annual_leave'AND tags?'ordinary_wage')OR EXISTS(SELECT 1 FROM jsonb_each_text(tags)x WHERE x.value NOT IN('include','exclude','not_applicable'))OR NOT EXISTS(SELECT 1 FROM public.ty_pay_item i WHERE i.adoption_id=a.id AND i.wage_tags@>tags)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 培训待遇须已核税及法定工资范围映射';END IF;RETURN public.fn_ty_lr_award_target(p.id,b.period);END;$$;
ALTER FUNCTION fn_ty_pay_extension_expected(bigint,bigint)RENAME TO fn_ty_pay_extension_expected_pre223;
ALTER FUNCTION fn_ty_pay_extension_key(bigint,bigint)RENAME TO fn_ty_pay_extension_key_pre223;
CREATE FUNCTION fn_ty_pay_extension_expected(batch_key bigint,adoption_key bigint)RETURNS numeric LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=adoption_key AND source_domain='training_award')THEN RETURN public.fn_ty_lr_pay_expected(batch_key,adoption_key);END IF;RETURN public.fn_ty_pay_extension_expected_pre223(batch_key,adoption_key);END;$$;
CREATE FUNCTION fn_ty_pay_extension_key(batch_key bigint,adoption_key bigint)RETURNS text LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=adoption_key AND source_domain='training_award')THEN RETURN public.fn_ty_lr_pay_key(batch_key,adoption_key);END IF;RETURN public.fn_ty_pay_extension_key_pre223(batch_key,adoption_key);END;$$;
-- Preserve the exact installed 221 provenance resolver, extending only the
-- known domain dispatch. Refuse migration if that contract has drifted.
DO $$DECLARE f text;definition text;needle text='IN(''statutory_calculation'',''performance_award'')';BEGIN FOREACH f IN ARRAY ARRAY['fn_ty_pay_authority_guard()','fn_ty_pay_reverse_provenance()']LOOP SELECT pg_get_functiondef(('public.'||f)::regprocedure)INTO definition;IF strpos(definition,needle)=0 THEN RAISE EXCEPTION '223 prerequisite payroll extension dispatch changed; review migration before applying';END IF;EXECUTE replace(definition,needle,'IN(''statutory_calculation'',''performance_award'',''training_award'')');END LOOP;END$$;
CREATE FUNCTION fn_ty_lr_source_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE rule public.ty_lr_rule%ROWTYPE;g public.ty_lr_grade%ROWTYPE;cer public.ty_lr_certificate%ROWTYPE;plan public.ty_lr_plan%ROWTYPE;ex public.ty_lr_exam%ROWTYPE;p public.ty_lr_paper%ROWTYPE;x jsonb;y jsonb;BEGIN
 IF TG_TABLE_NAME='ty_lr_application'THEN SELECT*INTO rule FROM public.ty_lr_rule WHERE id=NEW.rule_id;IF rule.status<>'published'OR rule.group_id<>NEW.group_id OR rule.company_id IS NOT NULL AND NOT public.fn_ty_lr_company_contains(rule.company_id,NEW.company_id) OR NEW.source_snapshot->'rule_config'IS DISTINCT FROM rule.config OR NEW.source_hash<>public.fn_ty_lr_hash(NEW.source_snapshot)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 采用须冻结实际已发布规则和完整来源';END IF;
 IF NEW.grade_id IS NOT NULL THEN SELECT*INTO g FROM public.ty_lr_grade WHERE id=NEW.grade_id;IF g.requirement_id<>NEW.requirement_id OR g.status<>'approved'OR NOT EXISTS(SELECT 1 FROM public.ty_lr_publication WHERE grade_id=g.id)OR EXISTS(SELECT 1 FROM public.ty_lr_grade WHERE status='approved'AND(previous_id=g.id OR g.attempt_id IS NOT NULL AND attempt_id=g.attempt_id AND version>g.version))OR NEW.source_snapshot->'grade'->>'source_hash'IS DISTINCT FROM g.source_hash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 采用必须当前同要求核准发布成绩';END IF;END IF;
 IF NEW.status IN('approved','applied')AND NEW.approved_by IS NULL OR NEW.status='applied'AND NEW.applied_by IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 未经真实独立核准执行不得称采用成功';END IF;
 IF TG_OP='INSERT'AND NEW.status<>'proposed'OR TG_OP='UPDATE'AND(OLD.status='applied'AND NEW IS DISTINCT FROM OLD OR OLD.status IN('cancelled','rejected')AND NEW.status<>OLD.status OR NEW.status='applied'AND OLD.status<>'approved')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 结果应用必须按提案核准执行且已采用不可覆盖';END IF;
 ELSIF TG_TABLE_NAME='ty_lr_assignment'THEN SELECT*INTO plan FROM public.ty_lr_plan WHERE id=NEW.plan_id FOR UPDATE;IF TG_OP='UPDATE'AND(NEW.group_id,NEW.company_id,NEW.person_id,NEW.employment_id,NEW.requirement_id,NEW.plan_id)IS DISTINCT FROM(OLD.group_id,OLD.company_id,OLD.person_id,OLD.employment_id,OLD.requirement_id,OLD.plan_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 既有学习分派不能换人或换要求根';END IF;IF NEW.state IN('assigned','completed')AND plan.capacity IS NOT NULL AND(SELECT count(*)FROM public.ty_lr_assignment a WHERE a.plan_id=plan.id AND a.state IN('assigned','completed')AND a.id<>NEW.id)>=plan.capacity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 培训名额已满';END IF;
 ELSIF TG_TABLE_NAME='ty_lr_paper'AND NEW.status='published'THEN IF jsonb_array_length(NEW.pool_snapshot)=0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 已发布试卷不能空卷';END IF;FOR x IN SELECT*FROM jsonb_array_elements(NEW.pool_snapshot)LOOP IF NOT EXISTS(SELECT 1 FROM public.ty_lr_question q JOIN public.ty_lr_question_key k ON k.question_id=q.id WHERE q.id=(x->>'id')::bigint AND q.group_id=NEW.group_id AND q.status='published'AND q.version=(x->>'version')::int AND k.answer=x->'answer'AND q.points=(x->>'points')::numeric)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 试卷题池必须冻结同集团已核题版及答案键';END IF;END LOOP;
 ELSIF TG_TABLE_NAME='ty_lr_attempt'AND TG_OP='INSERT'THEN SELECT*INTO ex FROM public.ty_lr_exam WHERE id=NEW.exam_id;SELECT*INTO p FROM public.ty_lr_paper WHERE id=ex.paper_id;IF jsonb_array_length(NEW.question_snapshot)=0 OR(SELECT count(*)FROM jsonb_array_elements(NEW.question_snapshot))<>(SELECT count(DISTINCT qi.value->>'id')FROM jsonb_array_elements(NEW.question_snapshot)qi(value))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 考卷不可空或重复题';END IF;FOR x IN SELECT*FROM jsonb_array_elements(NEW.question_snapshot)LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.pool_snapshot)pool_item(value) WHERE(x-'points')=(pool_item.value-'points'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 在考题面答案须来自实际冻结题池';END IF;END LOOP;
 ELSIF TG_TABLE_NAME='ty_lr_attendance'AND NEW.status='verified'THEN IF NEW.verified_by IS NULL OR NEW.credited_minutes IS NULL OR NEW.attendance_state='pending'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 待核/未知学时不得称已核定';END IF;
 ELSIF TG_TABLE_NAME='ty_lr_recognition'THEN SELECT*INTO cer FROM public.ty_lr_certificate WHERE id=NEW.certificate_id;IF coalesce((cer.conditions->>'course_completed')::boolean,false)AND NOT EXISTS(SELECT 1 FROM public.ty_lr_assignment a WHERE a.requirement_id=NEW.requirement_id AND a.state='completed')OR coalesce((cer.conditions->>'practical_passed')::boolean,false)AND NOT EXISTS(SELECT 1 FROM public.ty_lr_practical v JOIN public.ty_lr_assignment a ON a.id=v.assignment_id WHERE a.requirement_id=NEW.requirement_id AND v.status='verified'AND v.passed AND NOT EXISTS(SELECT 1 FROM public.ty_lr_practical newer WHERE newer.assignment_id=v.assignment_id AND newer.status='verified'AND newer.version>v.version))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 资格缺本次学习或实操权威完成条件';END IF;IF NEW.status='approved'AND NEW.approved_by IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 内部资格须真实独立核准';END IF;END IF;RETURN NEW;END;$$;
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['application','assignment','paper','attempt','attendance','recognition']LOOP EXECUTE format('CREATE TRIGGER ty_lr_%s_sources BEFORE INSERT OR UPDATE ON ty_lr_%s FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_source_guard()',n,n);END LOOP;END$$;
ALTER TABLE ty_lr_quota_event ADD UNIQUE(attempt_id,kind);
CREATE FUNCTION fn_ty_lr_quota_balance()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE r public.ty_lr_requirement%ROWTYPE;h integer;u integer;BEGIN SELECT*INTO r FROM public.ty_lr_requirement WHERE id=NEW.id;SELECT coalesce(sum(held_delta),0),coalesce(sum(used_delta),0)INTO h,u FROM public.ty_lr_quota_event WHERE requirement_id=r.id;IF r.held<>h OR r.used<>u THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 考试额度必须与不可变次数流水守恒';END IF;RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER ty_lr_quota_balance AFTER INSERT OR UPDATE ON ty_lr_requirement DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_quota_balance();
CREATE FUNCTION fn_ty_lr_requirement_identity()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF(NEW.group_id,NEW.company_id,NEW.person_id,NEW.employment_id,NEW.requirement_key,NEW.allowed_attempts)IS DISTINCT FROM(OLD.group_id,OLD.company_id,OLD.person_id,OLD.employment_id,OLD.requirement_key,OLD.allowed_attempts)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 稳定应考要求及允许次数不可通过改绑或复制重置';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_requirement_identity BEFORE UPDATE ON ty_lr_requirement FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_requirement_identity();
CREATE FUNCTION fn_ty_lr_exam_signatures()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE a public.ty_lr_attempt%ROWTYPE;e public.ty_lr_exam%ROWTYPE;p public.ty_lr_paper%ROWTYPE;BEGIN
 IF TG_TABLE_NAME='ty_lr_answer'THEN SELECT*INTO a FROM public.ty_lr_attempt WHERE id=NEW.attempt_id;IF NOT public.fn_ty_pr_bound_person(NEW.recorded_by,a.group_id,a.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 不能代签他人答卷答案';END IF;
 ELSIF TG_TABLE_NAME='ty_lr_attempt'THEN IF TG_OP='INSERT'AND NOT public.fn_ty_pr_bound_person(NEW.started_by,NEW.group_id,NEW.person_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 考试必须当前绑定本人开考';END IF;
 ELSE IF NEW.source_kind='exam'THEN SELECT*INTO a FROM public.ty_lr_attempt WHERE id=NEW.attempt_id;SELECT*INTO e FROM public.ty_lr_exam WHERE id=a.exam_id;SELECT*INTO p FROM public.ty_lr_paper WHERE id=e.paper_id;IF NEW.created_by<>e.grader_id OR NEW.status='approved'AND NEW.approved_by<>e.reviewer_id OR NEW.pass_percentage<>p.pass_percentage THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 阅卷签名、独立复核或合格线须来自冻结任务';END IF;END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_answer_signature BEFORE INSERT OR UPDATE ON ty_lr_answer FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_exam_signatures();
CREATE TRIGGER ty_lr_attempt_signature BEFORE INSERT OR UPDATE ON ty_lr_attempt FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_exam_signatures();
CREATE TRIGGER ty_lr_grade_signature BEFORE INSERT OR UPDATE ON ty_lr_grade FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_exam_signatures();
CREATE FUNCTION fn_ty_lr_minutes(assignment_key bigint)RETURNS numeric LANGUAGE sql STABLE SET search_path=''AS $$WITH latest AS(SELECT DISTINCT ON(a.session_id)a.*,s.starts_at,s.ends_at FROM public.ty_lr_attendance a JOIN public.ty_lr_session s ON s.id=a.session_id WHERE a.assignment_id=assignment_key AND a.status='verified'ORDER BY a.session_id,a.version DESC),ranges AS(SELECT range_agg(tstzrange(greatest(check_in,starts_at),least(check_out,ends_at),'[)'))v FROM latest WHERE check_in IS NOT NULL AND check_out IS NOT NULL AND least(check_out,ends_at)>greatest(check_in,starts_at)AND attendance_state IN('present','late','early'))SELECT coalesce((SELECT sum(extract(epoch FROM(upper(u)-lower(u)))/60)FROM ranges,unnest(v)u),0)$$;
CREATE FUNCTION fn_ty_lr_attendance_truth()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE s public.ty_lr_session%ROWTYPE;expected numeric;BEGIN SELECT*INTO s FROM public.ty_lr_session WHERE id=NEW.session_id;IF NEW.status='verified'THEN IF NEW.check_out>clock_timestamp()+interval '1 second'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 未来未发生的签到不能称实际出勤';END IF;IF NEW.attendance_state IN('present','late','early')THEN IF NEW.check_in IS NULL OR NEW.check_out IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 缺实际区间不得凭空填总学时';END IF;expected=greatest(0,extract(epoch FROM(least(NEW.check_out,s.ends_at)-greatest(NEW.check_in,s.starts_at)))/60);IF NEW.credited_minutes IS DISTINCT FROM round(expected,4)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 学时必须沿真实签到区间核定';END IF;ELSIF NEW.credited_minutes<>0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 缺席或请假不冒作到场学时';END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_attendance_truth BEFORE INSERT OR UPDATE ON ty_lr_attendance FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_attendance_truth();

ALTER TABLE ty_lr_grade ADD COLUMN occurred_on date NOT NULL DEFAULT app_today();
ALTER TABLE ty_lr_requirement ADD COLUMN historical_quota_pending boolean NOT NULL DEFAULT false;
CREATE FUNCTION fn_ty_lr_historical_quota_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_lr_requirement WHERE id=NEW.requirement_id AND historical_quota_pending)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 历史应考次数待核，不能默认零次继续同周期考试';END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_historical_quota_guard BEFORE INSERT ON ty_lr_attempt FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_historical_quota_guard();

CREATE FUNCTION fn_ty_lr_company_contains(owner_key bigint,child_key bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$WITH RECURSIVE tree AS(SELECT id,group_id FROM public.ty_company WHERE id=owner_key UNION ALL SELECT c.id,c.group_id FROM public.ty_company c JOIN tree p ON c.parent_company_id=p.id AND c.group_id=p.group_id)SELECT owner_key IS NULL OR EXISTS(SELECT 1 FROM tree WHERE id=child_key)$$;

ALTER TABLE ty_lr_discipline ADD COLUMN occurred_on date NOT NULL DEFAULT app_today();ALTER TABLE ty_lr_practical ADD COLUMN occurred_on date NOT NULL DEFAULT app_today();

ALTER TABLE ty_lr_grade ADD COLUMN expected_approved_id bigint REFERENCES ty_lr_grade(id);
CREATE FUNCTION fn_ty_lr_grade_head_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE current_key bigint;previous public.ty_lr_grade%ROWTYPE;BEGIN
 IF TG_OP='INSERT'AND NEW.status<>'proposed'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 正式成绩必须从待复核意图独立核准';END IF;
 IF NEW.previous_id IS NOT NULL THEN SELECT*INTO previous FROM public.ty_lr_grade WHERE id=NEW.previous_id;IF(previous.group_id,previous.requirement_id,previous.attempt_id)IS DISTINCT FROM(NEW.group_id,NEW.requirement_id,NEW.attempt_id)OR previous.version>=NEW.version THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 成绩更正必须原要求原答卷版本链';END IF;END IF;
 IF NEW.attempt_id IS NOT NULL AND NEW.status='approved'AND(TG_OP='INSERT'OR OLD.status<>'approved')THEN PERFORM id FROM public.ty_lr_attempt WHERE id=NEW.attempt_id FOR UPDATE;SELECT id INTO current_key FROM public.ty_lr_grade WHERE attempt_id=NEW.attempt_id AND status='approved'AND id<>NEW.id ORDER BY version DESC LIMIT 1;IF current_key IS DISTINCT FROM NEW.expected_approved_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='E_TY_CONFLICT: 此答卷已有新核准成绩，请重新阅卷预演，不覆盖当前头';END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lr_grade_head_guard BEFORE INSERT OR UPDATE ON ty_lr_grade FOR EACH ROW EXECUTE FUNCTION fn_ty_lr_grade_head_guard();
CREATE FUNCTION fn_ty_lr_recognition_current(recognition_key bigint,on_day date)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.ty_lr_recognition r JOIN public.ty_lr_certificate c ON c.id=r.certificate_id LEFT JOIN public.ty_lr_grade g ON g.id=r.grade_id
 WHERE r.id=recognition_key AND r.status='approved'AND r.valid_from<=on_day AND(r.valid_to IS NULL OR r.valid_to>on_day)AND(c.recognition_mode='once'OR(
 (NOT coalesce((c.conditions->>'exam_passed')::boolean,false)OR g.status='approved'AND g.passed AND EXISTS(SELECT 1 FROM public.ty_lr_publication WHERE grade_id=g.id)AND NOT EXISTS(SELECT 1 FROM public.ty_lr_grade n WHERE n.status='approved'AND(n.previous_id=g.id OR g.attempt_id IS NOT NULL AND n.attempt_id=g.attempt_id AND n.version>g.version)))
 AND(NOT coalesce((c.conditions->>'course_completed')::boolean,false)OR EXISTS(SELECT 1 FROM public.ty_lr_assignment a WHERE a.requirement_id=r.requirement_id AND a.state='completed'))
 AND(NOT coalesce((c.conditions->>'practical_passed')::boolean,false)OR EXISTS(SELECT 1 FROM public.ty_lr_practical p JOIN public.ty_lr_assignment a ON a.id=p.assignment_id WHERE a.requirement_id=r.requirement_id AND p.status='verified'AND p.passed AND NOT EXISTS(SELECT 1 FROM public.ty_lr_practical n WHERE n.assignment_id=p.assignment_id AND n.status='verified'AND n.version>p.version)))
 )))$$;
